/// <reference types="react" />
import { AxisScale, SharedAxisProps } from '@visx/axis';
import { TextProps } from '@visx/text';
/**
 * @internal
 */
export type Orientation = 'left' | 'right' | 'bottom';
/**
 * @internal
 */
export type TickLabelLayout = 'horizontal' | 'vertical';
/**
 * @internal
 */
export interface AxisProps extends SharedAxisProps<AxisScale> {
    width?: React.SVGAttributes<SVGSVGElement>['width'];
    height?: React.SVGAttributes<SVGSVGElement>['height'];
    containerSize: number;
    stroke?: string;
}
/**
 * @internal
 */
export type OrientedAxisProps = Omit<AxisProps, 'orientation' | 'width' | 'height'> & {
    width?: number;
    height?: number;
};
/**
 * @internal
 */
export type TextPropsRequired = Required<Pick<TextProps, 'fill' | 'fontFamily'>> & {
    fontSize: string;
    color: string;
};
/**
 * record of category id and category name
 * @internal
 */
export type TickCategory = Record<string, string>;
